def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 100:
        return 'D'
    if n == 99:
        return 'D'

    opp_c = 0
    opp_d = 0
    for h in history:
        if h[1] == 'C':
            opp_c += 1
        else:
            opp_d += 1

    # Exploit pure cooperators / forgiving strategies with a safe defection rate
    if opp_d == 0:
        if n < 2:
            return 'C'
        if n == 2:
            return 'D'
        if n == 3:
            return 'C'
        # For n >= 4, defect only if we have fewer than 2 defections in the last 8 rounds
        recent_me = history[-8:] if n >= 8 else history
        my_def_count = 0
        for h in recent_me:
            if h[0] == 'D':
                my_def_count += 1
        if my_def_count < 2:
            return 'D'
        return 'C'

    # General case: opponent has defected at least once
    recent = history[-10:] if n >= 10 else history
    recent_opp_d = 0
    for h in recent:
        if h[1] == 'D':
            recent_opp_d += 1
    recent_opp_c = len(recent) - recent_opp_d

    last_me, last_opp = history[-1]

    # Count retaliations to our initiations
    init_def = 0
    init_retaliated = 0
    for i in range(n - 1):
        if history[i][0] == 'D' and history[i][1] == 'C':
            init_def += 1
            if history[i+1][1] == 'D':
                init_retaliated += 1

    # Defect if opponent is very defection-heavy
    if opp_d >= opp_c and opp_d >= 3:
        if last_opp == 'C' and recent_opp_d <= 2:
            return 'C'
        return 'D'

    # Cooperate if opponent is very cooperative
    if recent_opp_d <= 1 and opp_d <= max(2, n // 10):
        if last_opp == 'D':
            return 'C'
        # Occasionally probe if we haven't been punished
        if init_retaliated == 0 and init_def > 0 and n > 20 and n < 90:
            if rng.random() < 0.1:
                return 'D'
        return 'C'

    # Main TFT with forgiveness
    if last_opp == 'D':
        if last_me == 'D':
            if recent_opp_d >= 3:
                if rng.random() < 0.5:
                    return 'C'
            return 'D'
        else:
            forgive_prob = 0.1
            if init_retaliated > 0:
                forgive_prob = 0.8
            elif recent_opp_d >= 3:
                forgive_prob = 0.4
            if rng.random() < forgive_prob:
                return 'C'
            return 'D'
    else:
        if last_me == 'D':
            return 'C'
        return 'C'
